function main(inputs) {
  var dt = String(inputs.datetime || "");
  var date = dt.slice(0, 10);
  var timeHM = dt.slice(0, 16);
  var raw = inputs.projects;
  if (typeof raw === "string") { try { raw = JSON.parse(raw); } catch (e) { raw = []; } }
  if (!Array.isArray(raw)) { raw = []; }
  var items = raw.slice(0, 10);

  function text(v) {
    if (v === undefined || v === null) { return "暂无"; }
    var s = String(v).trim();
    return s === "" ? "暂无" : s;
  }
  function num(v) {
    if (v === undefined || v === null) { return null; }
    var s = String(v).replace(/[,\s]/g, "");
    var n = Number(s);
    return isFinite(n) ? n : null;
  }
  function fmt(n) {
    if (n === null) { return "暂无"; }
    var neg = n < 0;
    var s = String(Math.abs(Math.round(n))).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return (neg ? "-" : "") + s;
  }
  function repoLink(p) {
    var repo = text(p.repo);
    if (repo === "暂无") { return "暂无"; }
    var url = text(p.url);
    if (url === "暂无") { url = "https://github.com/" + repo; }
    return "[" + repo + "](" + url + ")";
  }

  var table = "";
  var details = "";
  for (var i = 0; i < items.length; i++) {
    var p = items[i];
    table += "| " + (i + 1) + " | " + repoLink(p) + " | " + text(p.owner) + " | " + text(p.language) + " | " + fmt(num(p.stars)) + " | " + fmt(num(p.forks)) + " | " + text(p.todayStars) + " |\n";
  }
  for (var j = 0; j < items.length; j++) {
    var q = items[j];
    details += "### " + (j + 1) + ". " + repoLink(q) + "\n\n";
    details += "- **作者**：" + text(q.owner) + "\n";
    details += "- **主要语言**：" + text(q.language) + "\n";
    details += "- **Star**：" + fmt(num(q.stars)) + "　**Fork**：" + fmt(num(q.forks)) + "　**今日新增**：" + text(q.todayStars) + "\n";
    details += "- **描述**：" + text(q.descriptionZh) + "\n";
    details += "- **原文**：" + text(q.description) + "\n\n";
  }

  var report =
    "# GitHub 每日热门项目 Top 10\n\n" +
    "> 报告日期：" + date + "\n" +
    "> 数据来源：GitHub Trending\n" +
    "> 生成时间：" + timeHM + "\n\n" +
    "## 汇总一览\n\n" +
    "| 排名 | 项目 | 作者 | 主要语言 | Star | Fork | 今日新增 |\n" +
    "| ---- | ---- | ---- | ---- | ---- | ---- | ---- |\n" +
    table + "\n" +
    "## 项目详情\n\n" +
    details +
    "---\n\n" +
    "*本报告由工作流自动生成，数据来自 GitHub Trending。*\n";

  var filename = "github-top10-" + date + ".md";
  return { report: report, filename: filename, filePath: filename };
}

function main(inputs) {
  var html = String(inputs.html || "");
  var datetime = String(inputs.datetime || "");
  var dm = datetime.match(/^\d{4}-\d{2}-\d{2}/);
  var date = dm ? dm[0] : datetime.slice(0, 10);
  function decode(s) {
    return String(s).replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, "\"").replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
  }
  function stripTags(s) {
    return decode(String(s).replace(/<[^>]*>/g, "")).replace(/\s+/g, " ").trim();
  }
  function grab(re, s) {
    var m = s.match(re);
    return m ? m[1] : "";
  }
  function numText(t) {
    var m = String(t).match(/[\d.,]+/);
    return m ? m[0].replace(/,/g, "") : "0";
  }
  var blocks = html.match(/<article[^>]*class="Box-row"[^>]*>[\s\S]*?<\/article>/g) || [];
  if (blocks.length === 0) {
    blocks = html.match(/<article[^>]*>[\s\S]*?<\/article>/g) || [];
  }
  var items = [];
  for (var i = 0; i < blocks.length && items.length < 10; i++) {
    var a = blocks[i];
    var repo = stripTags(grab(/<h2[^>]*>[\s\S]*?<a[^>]*href="\/([^"#?]+)"/, a));
    if (!repo || repo.indexOf("/") < 0) { continue; }
    var desc = stripTags(grab(/<p[^>]*class="col-9[^"]*"[^>]*>([\s\S]*?)<\/p>/, a)) || stripTags(grab(/<p[^>]*>([\s\S]*?)<\/p>/, a));
    var lang = stripTags(grab(/itemprop="programmingLanguage">([^<]+)</, a)) || "未知";
    var starsText = numText(stripTags(grab(/href="\/[^"+]+\/stargazers"[^>]*>([\s\S]*?)<\/a>/, a)));
    var forksText = numText(stripTags(grab(/href="\/[^"+]+\/forks"[^>]*>([\s\S]*?)<\/a>/, a)));
    var tm = stripTags(a).match(/([\d.,]+)\s+stars?\s+today/i);
    var todayText = tm ? tm[1].replace(/,/g, "") : "0";
    items.push({
      rank: items.length + 1,
      repo: repo,
      url: "https://github.com/" + repo,
      description: desc || "暂无简介",
      language: lang,
      starsText: starsText,
      stars: parseFloat(starsText) || 0,
      todayStarsText: todayText,
      todayStars: parseFloat(todayText) || 0,
      forksText: forksText,
      forks: parseFloat(forksText) || 0
    });
  }
  return { date: date, count: items.length, items: items };
}

