function parseOrdersText(text) {
  var s = typeof text === 'string' ? text : '';
  if (s.trim().length === 0) {
    throw new Error('订单文件内容为空');
  }
  var data;
  try {
    data = JSON.parse(s.trim());
  } catch (e) {
    throw new Error('订单文件内容不是有效 JSON：' + (e && e.message ? e.message : String(e)));
  }
  if (!Array.isArray(data)) {
    throw new Error('订单文件必须是 JSON 数组，实际顶层为 ' + (data === null ? 'null' : typeof data));
  }
  return data;
}

function extractOrders(res) {
  if (Array.isArray(res)) {
    return res;
  }
  if (!res || typeof res !== 'object') {
    throw new Error('订单文件读取结果为空或结构异常');
  }
  if (!Array.isArray(res.lines)) {
    throw new Error('read 输出结构异常：缺少 lines 数组，顶层键=' + JSON.stringify(Object.keys(res)));
  }
  if (res.offset !== 1) {
    throw new Error('文件读取发生分页/偏移：offset=' + JSON.stringify(res.offset) + '，仅支持 offset=1 的完整单页读取');
  }
  if (typeof res.totalLines !== 'number') {
    throw new Error('read 输出结构异常：缺少数值 totalLines');
  }
  if (res.lines.length !== res.totalLines) {
    throw new Error('文件读取疑似截断：lines 数量 ' + res.lines.length + ' 与 totalLines ' + res.totalLines + ' 不一致');
  }
  var parts = [];
  for (var i = 0; i < res.lines.length; i++) {
    var ln = res.lines[i];
    if (!ln || typeof ln !== 'object' || typeof ln.text !== 'string' || ln.number !== i + 1) {
      throw new Error('read 输出行结构异常：第 ' + (i + 1) + ' 条记录缺少 text 或行号不连续');
    }
    parts.push(ln.text);
  }
  return parseOrdersText(parts.join('\n'));
}

function main(inputs) {
  var res = inputs.readValue;
  if (res === undefined || res === null) {
    var raw = inputs.readText;
    if (typeof raw !== 'string' || raw.trim().length === 0) {
      throw new Error('未获得读取订单文件节点的输出（value 与 text 均为空）');
    }
    try {
      res = JSON.parse(raw.trim());
    } catch (e) {
      throw new Error('读取输出不是有效 JSON：' + (e && e.message ? e.message : String(e)));
    }
  }
  var orders = extractOrders(res);
  return { orders: orders };
}

function main(inputs) {
  var orders = inputs.orders;
  if (!Array.isArray(orders)) throw new Error('orders 必须是数组');
  var paid = [];
  for (var i = 0; i < orders.length; i++) {
    var o = orders[i];
    if (o && typeof o === 'object' && o.status === 'paid') paid.push(o);
  }
  var totalCents = 0;
  var byCategory = {};
  var seen = [];
  for (var j = 0; j < paid.length; j++) {
    var p = paid[j];
    var amt = p.amountCents;
    if (typeof amt !== 'number' || !isFinite(amt) || Math.floor(amt) !== amt) {
      throw new Error('amountCents 必须是整数分，订单 id=' + String(p.id));
    }
    var cat = String(p.category);
    if (!Object.prototype.hasOwnProperty.call(byCategory, cat)) {
      byCategory[cat] = 0;
      seen.push(cat);
    }
    byCategory[cat] += amt;
    totalCents += amt;
  }
  var categories = [];
  for (var k = 0; k < seen.length; k++) {
    categories.push({ name: seen[k], cents: byCategory[seen[k]] });
  }
  var summary = { paidCount: paid.length, totalCents: totalCents, byCategory: byCategory };
  return {
    paidCount: paid.length,
    totalCents: totalCents,
    byCategory: byCategory,
    categories: categories,
    summaryJson: JSON.stringify(summary, null, 2) + '\n'
  };
}

