function main(inputs) {
  var errors = [];
  var records = inputs.records;
  var threshold = inputs.threshold;
  var outputPath = inputs.outputPath;

  if (typeof outputPath !== 'string' || outputPath.length === 0) {
    errors.push('outputPath 必须为非空字符串，实际收到：' + JSON.stringify(outputPath));
  }

  if (typeof threshold !== 'number' || !isFinite(threshold) || Math.floor(threshold) !== threshold || threshold < 0) {
    errors.push('threshold 必须为非负整数，实际收到：' + JSON.stringify(threshold));
  }

  var list = null;
  if (typeof records !== 'string') {
    errors.push('records 必须为 JSON 数组文本，实际收到：' + JSON.stringify(records));
  } else {
    try {
      var parsed = JSON.parse(records);
      if (!Array.isArray(parsed)) {
        errors.push('records 必须是合法 JSON 数组');
      } else {
        list = parsed;
        for (var i = 0; i < list.length; i++) {
          var item = list[i];
          if (item === null || typeof item !== 'object' || Array.isArray(item)) {
            errors.push('records[' + i + '] 必须是对象');
            continue;
          }
          if (typeof item.sku !== 'string' || item.sku.length === 0) {
            errors.push('records[' + i + '].sku 必须为非空字符串，实际收到：' + JSON.stringify(item.sku));
          }
          if (typeof item.stock !== 'number' || !isFinite(item.stock) || Math.floor(item.stock) !== item.stock || item.stock < 0) {
            errors.push('records[' + i + '].stock 必须为非负整数，实际收到：' + JSON.stringify(item.stock));
          }
        }
      }
    } catch (err) {
      errors.push('records 不是合法 JSON：' + err.message);
    }
  }

  if (errors.length > 0) {
    throw new Error('输入校验失败：' + errors.join('；'));
  }

  var lines = [];
  var total = 0;
  for (var j = 0; j < list.length; j++) {
    var rec = list[j];
    if (rec.stock < threshold) {
      var need = threshold - rec.stock;
      lines.push({ sku: rec.sku, restock: need });
      total += need;
    }
  }

  return { lines: lines, count: lines.length, total: total };
}

